const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define global ocean geometry (exclude land)
  const oceanBounds = ee.Geometry.Rectangle([-180, -90, 180, 90]);

  // Time periods for comparison
  const period1 = ['2002-01-01', '2004-12-31']; // Early period
  const period2 = ['2020-01-01', '2022-12-31']; // Recent period

  // MODIS Aqua Ocean Color data - chlorophyll as proxy for greenness
  const modisCol1 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(period1[0], period1[1])
    .select(['chlor_a', 'qual_sst']);

  const modisCol2 = ee.ImageCollection('NASA/OCEANDATA/MODIS-Aqua/L3SMI')
    .filterDate(period2[0], period2[1])
    .select(['chlor_a', 'qual_sst']);

  // Check collection sizes
  const size1 = modisCol1.size().getInfo();
  const size2 = modisCol2.size().getInfo();

  console.log(`2002-2004 Images: ${size1}`);
  console.log(`2020-2022 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Function to process images - mask poor quality and land
  function processImage(img) {
    // Mask poor quality (quality flag > 0)
    const qualityMask = img.select('qual_sst').eq(0);
    // Mask very high chlorophyll values (likely errors)
    const chlorMask = img.select('chlor_a').lt(100);
    return img.select('chlor_a')
      .updateMask(qualityMask)
      .updateMask(chlorMask);
  }

  // Process collections
  const processed1 = modisCol1.map(processImage).mean();
  const processed2 = modisCol2.map(processImage).mean();

  // Calculate statistics
  const stats1 = processed1.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: oceanBounds,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = processed2.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: oceanBounds,
    scale: 10000,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1.chlor_a_mean;
  const mean2 = stats2.chlor_a_mean;
  const count1 = stats1.chlor_a_count;
  const count2 = stats2.chlor_a_count;

  console.log(`2002-2004 Mean Chlorophyll: ${mean1 ? mean1.toFixed(4) : 'N/A'}, Pixels: ${count1}`);
  console.log(`2020-2022 Mean Chlorophyll: ${mean2 ? mean2.toFixed(4) : 'N/A'}, Pixels: ${count2}`);

  // Validation checks
  if (count1 === 0 || count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  if (mean1 === null || mean2 === null || !isFinite(mean1) || !isFinite(mean2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine answer - greener means higher chlorophyll
  const change = ((mean2 - mean1) / mean1) * 100;
  console.log(`Change: ${change.toFixed(2)}%`);

  // Consider significant shift as > 5% increase
  if (change > 5) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
